<script setup lang="ts">
import {computed,ref} from 'vue'
import {useRoute} from 'vue-router'
import {useDb} from '../../../stores/db'
import {useSession} from '../../../stores/session'
import {StatusBadge} from '../../../components/shared'
import {fmtMoney} from '../../../lib/money'
import {importUnits} from '../domain'
const route=useRoute(),db=useDb(),session=useSession(),tab=ref(String(route.query.tab||'overview')),status=ref(''),block=ref(''),preview=ref<ReturnType<typeof importUnits>|null>(null)
const project=computed(()=>db.data.projects.find(item=>item.id===route.params.id))
const units=computed(()=>db.data.units.filter(unit=>unit.projectId===project.value?.id&&(!status.value||unit.status===status.value)&&(!block.value||unit.blockId===block.value)&&(session.activePersona?.activeRole!=='agent'||unit.allocatedAgencyIds.includes(session.activePersona.orgId))))
const stages=[
  ['Deal acquisition and structuring','BD/SP',['Deal diligence','Package proposal','Internal verification','LOA and legal']],
  ['Project set-up and governance','BD/SP',['Internal briefing','System and process set-up','Team and access','Funder confirmation']],
  ['Marketing support','MKT',['Pre-launch materials','Launch event','Roadshows']],
  ['Cross-agency arrangement','BD/SP',['Agent briefing','Bank and valuation liaison','Package update support']],
  ['Pre-SPA signing','SA',['Booking fee transfer','Signing confirmation','Project tracking update']],
  ['Post-SPA signing','CC',['Master list update','Claim forecast','Cash-flow update','Accounting liaison']],
  ['Pre-VP','BD/SP + OPS',['Construction updates','Renovation review','Property management sync']],
  ['Post-VP','OPS',['Key collection','Defects','Renovation','Rental review','Portfolio update']],
] as const
const sampleCsv=`A-01-01,available,45000000\nA-01-02,available,46000000\nA-01-01,available,47000000\nA-01-03,invalid,48000000\nA-01-04,available,\nA-01-05,blocked,50000000`
function validate(){if(!project.value)return;preview.value=importUnits(project.value,sampleCsv.split('\n'))}
</script>
<template><div v-if="project" class="page"><header class="page-header"><div><p class="eyebrow">{{project.mode==='exclusive'?'Exclusive project':'Developer-JV'}}</p><h1>{{project.name}}</h1><p>One project view across lifecycle, units, pricing and agency scope.</p></div><StatusBadge :label="project.status"/></header><div class="actions"><el-button v-for="item in ['overview','lifecycle','inventory','pricing','agency','setup']" :key="item" :type="tab===item?'primary':''" @click="tab=item">{{item[0].toUpperCase()+item.slice(1)}}</el-button></div>
<section v-if="tab==='overview'" class="card-grid"><article class="card"><StatusBadge label="Exclusive relationship"/><h2>Business mode</h2><p>Exclusive: signed undertaking plus exclusive agreement. Agency allocation grants a sales scope and is not ownership.</p></article><article class="card"><h2>Hold policy</h2><p class="kpi-value">{{project.holdPolicy.minutes}} min</p><p>Policy {{project.holdPolicy.policyVersion}}</p></article><article class="card"><h2>Booking fee policy</h2><p class="kpi-value">{{fmtMoney(project.bookingFeePolicyMinor)}}</p></article></section>
<section v-else-if="tab==='lifecycle'" class="card"><h2>Project Lifecycle Framework</h2><div class="data-list"><article v-for="(stage,index) in stages" :key="stage[0]" class="card"><div class="actions"><strong>{{index+1}}. {{stage[0]}}</strong><StatusBadge :label="stage[1]" tone="info"/><StatusBadge :label="index<4?'done':'in progress'"/></div><p>{{stage[2].join(' · ')}}</p><span class="source-meta">PIVO-linked activities available; manual activities remain clearly owned.</span></article></div><p class="source-meta">Enabling functions: project management · documentation and compliance · finance and control · communication management · data and system management.</p></section>
<section v-else-if="tab==='inventory'" class="page"><div class="card filter-bar"><label>Status<select v-model="status"><option value="">All statuses</option><option v-for="s in ['available','reserved','booked','sold','blocked']" :key="s">{{s}}</option></select></label><label>Block<select v-model="block"><option value="">All blocks</option><option v-for="b in project.blocks" :key="b.id" :value="b.id">{{b.name}}</option></select></label></div><div class="card"><h2>Grid by floor</h2><div class="card-grid"><button v-for="unit in units" :key="unit.id" class="persona-card"><strong>{{unit.unitNo}}</strong><br><StatusBadge :label="unit.status"/><br><span class="source-meta">{{fmtMoney(unit.listPriceMinor)}}</span></button></div></div><div class="card table-scroll"><h2>Accessible unit table</h2><el-table :data="units"><el-table-column prop="unitNo" label="Unit" min-width="110"/><el-table-column label="Status" min-width="120"><template #default="{row}"><StatusBadge :label="row.status"/></template></el-table-column><el-table-column label="List price" min-width="140"><template #default="{row}">{{fmtMoney(row.listPriceMinor)}}</template></el-table-column><el-table-column label="Version" min-width="100"><template #default="{row}">v{{row.version}}</template></el-table-column></el-table></div></section>
<section v-else-if="tab==='pricing'" class="card"><h2>Pricing and packages</h2><div class="table-scroll"><el-table :data="db.data.prices.filter(p=>p.projectId===project?.id)"><el-table-column prop="packageName" label="Package"/><el-table-column label="Status"><template #default="{row}"><StatusBadge :label="row.status"/></template></el-table-column><el-table-column label="Booking deposit"><template #default="{row}">{{fmtMoney(row.bookingDepositMinor)}}</template></el-table-column><el-table-column label="Buyer charges"><template #default="{row}">{{fmtMoney(row.buyerChargesMinor)}}</template></el-table-column></el-table></div><p>PIVO B2B service fee: separate fixed 10% of approved eligible gross agency commission. Existing contracts and posted commission history are never rewritten.</p></section>
<section v-else-if="tab==='agency'" class="card"><h2>Agency scope</h2><el-table :data="db.data.agencyAgreements"><el-table-column prop="orgId" label="Agency"/><el-table-column label="Commission"><template #default="{row}">{{row.dealCommissionBp/100}}%</template></el-table-column><el-table-column prop="holdLimit" label="Hold limit"/><el-table-column label="Pricing visible"><template #default="{row}"><StatusBadge :label="row.pricingVisible?'Yes':'No'"/></template></el-table-column></el-table></section>
<section v-else class="page"><div class="card"><h2>Import preview</h2><p>CSV rows include a duplicate key, missing price and invalid status. Invalid rows are rejected before commit.</p><el-button @click="validate">Preview CSV</el-button><div v-if="preview"><p>Accepted: {{preview.accepted.length}} · Rejected: {{preview.rejected.length}}</p><p v-for="r in preview.rejected" :key="r.row" class="form-error">Row {{r.row}}: {{r.reason}}</p></div></div><div class="card"><h2>Publication</h2><p>Blocked until approval, effective date and agency scope are valid.</p><StatusBadge label="Blocked pending approval"/></div></section></div>
</template>
